import React from 'react';
import '../styles/newsevents.css';

function NewsEvents() {
  return (
    <div className="news">
      <h2>News & Events</h2>
      <p>WE4HIM participated in the first ever International Day of the Boy Child, held at Nyikendo Secondary School on May 6, 2024.</p>
    </div>
  );
}

export default NewsEvents;
